import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

export class Store {
  constructor(file) {
    this.file = file;
  }

  async #read() {
    try {
      const parsed = JSON.parse(await readFile(this.file, 'utf8'));
      return Array.isArray(parsed.books) ? parsed.books : [];
    } catch (err) {
      if (err.code === 'ENOENT') return [];
      throw err;
    }
  }

  async #write(books) {
    // Write to a temp file and rename so a crash mid-write can't truncate the data file.
    await mkdir(dirname(this.file), { recursive: true });
    const tmp = `${this.file}.${process.pid}.tmp`;
    await writeFile(tmp, JSON.stringify({ books }, null, 2) + '\n');
    await rename(tmp, this.file);
  }

  async list() {
    const books = await this.#read();
    return {
      reading: books
        .filter((b) => !b.finishedAt)
        .sort((a, b) => b.addedAt.localeCompare(a.addedAt)),
      finished: books
        .filter((b) => b.finishedAt)
        .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt)),
    };
  }

  async get(id) {
    const books = await this.#read();
    return books.find((b) => b.id === id) ?? null;
  }

  async add({ title, author, notes = '' }) {
    title = title?.trim();
    author = author?.trim();
    if (!title) throw new ValidationError('Title is required.');
    if (!author) throw new ValidationError('Author is required.');

    const books = await this.#read();
    let id;
    do {
      id = randomBytes(4).toString('hex');
    } while (books.some((b) => b.id === id));

    const book = {
      id,
      title,
      author,
      notes: notes.trim(),
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    await this.#write(books);
    return book;
  }

  async finish(id) {
    return this.#update(id, (book) => {
      if (!book.finishedAt) book.finishedAt = new Date().toISOString();
    });
  }

  async setNotes(id, notes) {
    return this.#update(id, (book) => {
      book.notes = (notes ?? '').trim();
    });
  }

  async #update(id, mutate) {
    const books = await this.#read();
    const book = books.find((b) => b.id === id);
    if (!book) return null;
    mutate(book);
    await this.#write(books);
    return book;
  }
}

export class ValidationError extends Error {}

