const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escape(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  :root { color-scheme: light dark; }
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; }
  h1, h2 { line-height: 1.2; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: .5rem 0; border-bottom: 1px solid #8884; }
  ul.books li a { font-weight: 600; }
  .author, .meta { opacity: .7; }
  .empty { opacity: .6; font-style: italic; }
  form.add, form.notes { display: grid; gap: .6rem; margin-top: 1rem; }
  label { display: grid; gap: .2rem; }
  input, textarea { font: inherit; padding: .4rem; }
  textarea { min-height: 6rem; }
  button { font: inherit; padding: .4rem .9rem; cursor: pointer; }
  .notes-text { white-space: pre-wrap; }
  .share { display: flex; gap: .5rem; align-items: center; margin-top: 2rem; }
  .share input { flex: 1; }
  .error { color: #c33; }
  .actions { margin: 1.5rem 0; }
</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function bookItem(book) {
  return `<li>
  <a href="/books/${escape(book.id)}">${escape(book.title)}</a>
  <span class="author">by ${escape(book.author)}</span>
  ${book.finishedAt ? `<span class="meta"> · finished ${formatDate(book.finishedAt)}</span>` : ''}
</li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${escape(emptyText)}</p>`;
  return `<ul class="books">${books.map(bookItem).join('\n')}</ul>`;
}

export function homePage({ reading, finished }, { error, values = {} } = {}) {
  return layout(
    'My Books',
    `<h1><a href="/">My Books</a></h1>

<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
${error ? `<p class="error">${escape(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required value="${escape(values.title)}"></label>
  <label>Author <input name="author" required value="${escape(values.author)}"></label>
  <label>Notes <textarea name="notes">${escape(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, shareUrl) {
  return layout(
    book.title,
    `<p><a href="/">← All books</a></p>
<h1>${escape(book.title)}</h1>
<p class="author">by ${escape(book.author)}</p>
<p class="meta">${
      book.finishedAt
        ? `Finished ${formatDate(book.finishedAt)}`
        : `Currently reading · started ${formatDate(book.addedAt)}`
    }</p>

${
  book.finishedAt
    ? ''
    : `<form class="actions" method="post" action="/books/${escape(book.id)}/finish">
  <button type="submit">Mark as finished</button>
</form>`
}

<h2>Notes</h2>
<form class="notes" method="post" action="/books/${escape(book.id)}/notes">
  <textarea name="notes" placeholder="No notes yet.">${escape(book.notes)}</textarea>
  <div><button type="submit">Save notes</button></div>
</form>

<div class="share">
  <label for="share">Share link</label>
  <input id="share" readonly value="${escape(shareUrl)}" onfocus="this.select()">
</div>`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<h1>Book not found</h1><p><a href="/">← All books</a></p>`);
}

