    const store = new Store(file);
    const book = await store.add({ title: '  Dune ', author: 'Frank Herbert', notes: 'Spice.' });

    expect(book).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.', finishedAt: null });
    expect(book.id).toMatch(/^[a-f0-9]{8}$/);

    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk.books).toEqual([book]);
  });

  it('survives a restart by re-reading the file', async () => {
    const book = await new Store(file).add({ title: 'Dune', author: 'Frank Herbert' });
    const reopened = new Store(file);
    expect(await reopened.get(book.id)).toEqual(book);
  });

  it('rejects books without a title or author', async () => {
    const store = new Store(file);
    await expect(store.add({ title: '', author: 'X' })).rejects.toBeInstanceOf(ValidationError);
    await expect(store.add({ title: 'X', author: '  ' })).rejects.toBeInstanceOf(ValidationError);
    expect(await store.list()).toEqual({ reading: [], finished: [] });
  });

