    expect(reading.map((x) => x.id)).toEqual([b.id]);
    expect(done.map((x) => x.id)).toEqual([a.id]);
  });

  it('does not change the finished date when finishing twice', async () => {
    const store = new Store(file);
    const { id } = await store.add({ title: 'A', author: 'A' });
    const first = await store.finish(id);
    const second = await store.finish(id);
    expect(second.finishedAt).toBe(first.finishedAt);
  });

  it('updates notes', async () => {
    const store = new Store(file);
    const { id } = await store.add({ title: 'A', author: 'A' });
    await store.setNotes(id, '  Loved chapter 3.  ');
    expect((await store.get(id)).notes).toBe('Loved chapter 3.');
  });

  it('returns null for unknown ids', async () => {
    const store = new Store(file);
    expect(await store.get('nope')).toBeNull();
    expect(await store.finish('nope')).toBeNull();
    expect(await store.setNotes('nope', 'x')).toBeNull();
  });
});

