    expect(page).toContain('by Frank Herbert');
    expect(page).toContain('Spice &amp; sand');
    expect(page).toContain(`${base}${location}`); // share link
    expect(page).toContain('Mark as finished');

    const home = await (await fetch(base + '/')).text();
    expect(home).toContain(`href="${location}"`);
  });

  it('re-renders the form with an error when the title is missing', async () => {
    const res = await post('/books', { title: '', author: 'Someone' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('value="Someone"');
  });

  it('marks a book as finished', async () => {
    const { id } = await store.add({ title: 'A', author: 'B' });
    const res = await post(`/books/${id}/finish`, {});
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(`/books/${id}`);

    const page = await (await fetch(base + `/books/${id}`)).text();
    expect(page).toContain('Finished');
    expect(page).not.toContain('Mark as finished');
    expect((await store.get(id)).finishedAt).toBeTruthy();
  });

  it('saves notes from the book page', async () => {
    const { id } = await store.add({ title: 'A', author: 'B' });
    const res = await post(`/books/${id}/notes`, { notes: 'Great ending.' });
    expect(res.status).toBe(303);
    expect((await store.get(id)).notes).toBe('Great ending.');
  });

  it('escapes HTML in book fields', async () => {
    const { id } = await store.add({ title: '<script>alert(1)</script>', author: 'B' });
    const page = await (await fetch(base + `/books/${id}`)).text();
    expect(page).not.toContain('<script>alert(1)</script>');
    expect(page).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
  });

  it('returns 404 for unknown books and routes', async () => {
    expect((await fetch(base + '/books/deadbeef')).status).toBe(404);
    expect((await fetch(base + '/nope')).status).toBe(404);
    expect((await post('/books/deadbeef/finish', {})).status).toBe(404);
  });
});
